// config/loadConfig.js
const fs = require('fs');
const path = require('path');
const xml2js = require('xml2js');

/**
 * 加载应用配置文件
 * 支持 XML 格式，用于定义功能开关和参数
 */
async function loadConfig(configPath) {
  try {
    // 1. 校验文件存在性
    if (!fs.existsSync(configPath)) {
      throw new Error(`Config file not found: ${configPath}`);
    }

    // 2. 读取配置文件内容
    const xmlContent = fs.readFileSync(configPath, 'utf8');

    // 3. 解析 XML 配置
    const parser = new xml2js.Parser({
      explicitArray: false,
      trim: true
    });

    // 4. 将 XML 转换为 JavaScript 对象
    const result = await parser.parseStringPromise(xmlContent);

    // 5. 提取配置项
    const config = {
      featureFlags: result.config?.features || {},
      database: result.config?.database || {},
      cache: result.config?.cache || {},
      logging: result.config?.logging || {}
    };

    // 6. 验证必要配置项
    if (!config.database.host || !config.database.port) {
      throw new Error('Database configuration incomplete');
    }

    return config;
  } catch (err) {
    console.error(`Failed to load config from ${configPath}:`, err.message);
    throw err;
  }
}

module.exports = { loadConfig };

