// routes/passwordReset.js
const express = require('express');
const crypto = require('crypto');
const db = require('../db');
const { sendEmail } = require('../mailer');

const router = express.Router();

// 用于临时存储重置令牌（生产环境应使用 Redis 等带过期时间的存储）
const tokenStore = new Map();

// 辅助函数：规范化邮箱地址（去除空白、转为小写）
function normalizeEmail(email) {
  return email.trim().toLowerCase();
}

// 辅助函数：校验邮箱格式
function isValidEmail(email) {
  const re = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return re.test(email);
}

// 辅助函数：生成 32 字节的随机令牌（hex 编码）
function generateToken() {
  return crypto.randomBytes(32).toString('hex');
}

// 辅助函数：从请求中提取邮箱（兼容 query 和 body）
function extractEmail(req) {
  const raw = req.body.email || req.query.email || '';
  return normalizeEmail(raw);
}

// 辅助函数：验证令牌格式（必须为 64 位 hex 字符串）
function isValidToken(token) {
  return typeof token === 'string' && /^[a-f0-9]{64}$/.test(token);
}

// 辅助函数：将令牌与邮箱绑定存储（带 15 分钟过期）
function storeToken(email, token) {
  const expiresAt = Date.now() + 15 * 60 * 1000;
  tokenStore.set(token, { email, expiresAt });
  // 定期清理过期条目（简化处理）
  setTimeout(() => tokenStore.delete(token), 16 * 60 * 1000);
}

// 路由 1：请求密码重置（发送邮件）
router.post('/request-reset', async (req, res) => {
  const email = extractEmail(req);

  // 防御 1：邮箱格式校验（阻断无效输入）
  if (!isValidEmail(email)) {
    return res.status(400).json({ error: 'Invalid email format' });
  }

  // 防御 2：查询用户是否存在（不存在也返回成功，防止用户枚举）
  const user = await db.findUserByEmail(email);
  if (!user) {
    // 模拟发送延迟，避免时序攻击
    await new Promise(r => setTimeout(r, 100 + Math.random() * 200));
    return res.status(200).json({ message: 'If the email exists, a reset link has been sent.' });
  }

  // 生成令牌并存储
  const token = generateToken();
  storeToken(email, token);

  // 构造重置链接（注意：令牌作为路径参数，不放入 query）
  const resetUrl = `https://example.com/reset-password/${token}`;
  await sendEmail(email, 'Password Reset', `Click here: ${resetUrl}`);

  return res.status(200).json({ message: 'If the email exists, a reset link has been sent.' });
});

// 路由 2：执行密码重置
router.post('/confirm-reset', async (req, res) => {
  const { token, newPassword } = req.body;

  // 防御 3：令牌格式校验（严格正则，阻断路径遍历/注入）
  if (!isValidToken(token)) {
    return res.status(400).json({ error: 'Invalid token format' });
  }

  // 防御 4：从存储中查找令牌（不直接使用用户输入作为 key）
  const record = tokenStore.get(token);
  if (!record) {
    return res.status(400).json({ error: 'Invalid or expired token' });
  }

  // 防御 5：检查令牌是否过期
  if (Date.now() > record.expiresAt) {
    tokenStore.delete(token);
    return res.status(400).json({ error: 'Token expired' });
  }

  // 防御 6：新密码强度校验（至少 8 位，含字母和数字）
  if (typeof newPassword !== 'string' || newPassword.length < 8 || !/[a-zA-Z]/.test(newPassword) || !/[0-9]/.test(newPassword)) {
    return res.status(400).json({ error: 'Weak password' });
  }

  // 执行更新（此处使用参数化查询，避免 SQL 注入）
  const hashedPassword = crypto.createHash('sha256').update(newPassword).digest('hex');
  const updated = await db.updatePassword(record.email, hashedPassword);

  if (updated) {
    // 使用后立即删除令牌（一次性使用）
    tokenStore.delete(token);
    return res.status(200).json({ message: 'Password updated successfully' });
  } else {
    return res.status(500).json({ error: 'Update failed' });
  }
});

module.exports = router;

