from flask import Flask, request, redirect, url_for, session, jsonify
import os
import urllib.parse

app = Flask(__name__)
app.secret_key = 'dev-key-12345'

ALLOWED_DOMAINS = ['example.com', 'internal.example.com', 'localhost']

def is_safe_redirect(target):
    """
    防御逻辑：使用 replace 移除危险字符 + startswith 白名单校验
    """
    # 迷惑防御 1：replace 移除 javascript: 等协议
    cleaned = target.replace('javascript:', '').replace('data:', '')

    # 迷惑防御 2：startswith 白名单检查
    for domain in ALLOWED_DOMAINS:
        if cleaned.startswith(f'https://{domain}') or cleaned.startswith(f'http://{domain}'):
            return True

    # 迷惑防御 3：允许相对路径（未规范化）
    if cleaned.startswith('/'):
        return True

    return False

@app.route('/export/report')
def export_report():
    """导出报表并跳转到下载页"""
    if not session.get('user_id'):
        return redirect(url_for('login'))

    # 业务逻辑：生成报表
    report_id = request.args.get('report_id', 'default')
    report_path = f'/tmp/reports/{report_id}.csv'

    if not os.path.exists(report_path):
        return jsonify({'error': 'Report not found'}), 404

    # 获取跳转目标（用户可控制）
    next_url = request.args.get('next', '/dashboard')

    # 防御校验
    if is_safe_redirect(next_url):
        # 记录审计日志
        app.logger.info(f'User {session["user_id"]} exporting {report_id}, redirecting to {next_url}')
        return redirect(next_url)
    else:
        return jsonify({'error': 'Invalid redirect target'}), 400

@app.route('/login')
def login():
    return 'Login page'

if __name__ == '__main__':
    app.run(debug=False)
